with with_gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 1 hour then 1 else 0 end as is_new_session from device_readings), islands as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from with_gaps) select device_code, case when session_id >= 8 then 'PREMIUM' else 'STANDARD' end as session_id_tier, case when is_new_session >= 1 then 'PREMIUM' else 'STANDARD' end as is_new_session_tier, sum(case when device_code = 'DV-01' then status_bits else 0 end) as dv_01_status_bits, count(distinct device_code) as distinct_device_codes, count(case when device_code = 'DV-03' then 1 end) as dv_03_count, grouping(device_code) as grouping_level from islands group by rollup (device_code, case when session_id >= 8 then 'PREMIUM' else 'STANDARD' end, case when is_new_session >= 1 then 'PREMIUM' else 'STANDARD' end)
